with paid_orders as (select customer_id, count(*) paid_count, sum(amount) paid_amount from orders where status = 'paid' and created_at >= date '2026-04-01' group by customer_id), pending_orders as (select customer_id, count(*) pending_count, sum(amount) pending_amount from orders where status = 'pending' and created_at >= date '2026-04-01' group by customer_id) select customer_id, paid_count order_count, paid_amount total_amount, 'paid' bucket from paid_orders union all select customer_id, pending_count order_count, pending_amount total_amount, 'pending' bucket from pending_orders order by customer_id, bucket;
